from __builtins__ import *
# 淘汰候选归档：lb_sunflowers | 原实验路径 .codex/leaderboard-astra/sunflowers-cut-planner/lb_planner.py
# 私有固定输入规划计费组件；没有种收，不代表完整榜单。
def lb_planner():
    deadline = get_time() + 120
    positions = []
    for worker in range(32):
        positions.append(worker * 32 + 31)
    beginning = get_tick_count()
    plans = []
    for rank in range(9):
        cells = buckets[rank]
        phase = get_tick_count()
        prefix = [0]
        for index in range(1, len(cells)):
            prefix.append(prefix[-1] + distance(cells[index - 1], cells[index]) + 1)
        # 按真实末点的Hilbert环序插入排序，显式计费，不借Python sorted。
        order = []
        first = cells[0]
        for worker in range(32):
            key = (positions[worker] - first) % 1024
            index = len(order)
            order.append(worker)
            while index > 0 and (positions[order[index - 1]] - first) % 1024 > key:
                order[index] = order[index - 1]
                index -= 1
            order[index] = worker
        low = 1
        high = 400
        while low < high:
            if get_time() > deadline:
                quick_print("planner_failed", rank, "deadline", get_time())
                return
            middle = (low + high) // 2
            covered, cuts = fill(positions, cells, prefix, order, middle)
            if covered:
                high = middle
            else:
                low = middle + 1
        covered, cuts = fill(positions, cells, prefix, order, low)
        if not covered:
            quick_print("planner_failed", rank, "coverage", low)
            return
        routes = []
        for worker in range(32):
            start, end = cuts[worker]
            route = cells[start:end]
            routes.append(route)
            if end > start:
                positions[worker] = cells[end - 1]
        plans.append(routes)
        quick_print("planner_rank", rank, low, get_tick_count() - phase, order, cuts)
    quick_print("planner_done", get_tick_count() - beginning, get_time(), positions, plans)


def distance(a, b):
    pa = curve[a]
    pb = curve[b]
    dx = abs(pa[0] - pb[0])
    dy = abs(pa[1] - pb[1])
    if dx > 16:
        dx = 32 - dx
    if dy > 16:
        dy = 32 - dy
    return dx + dy


def fill(positions, cells, prefix, order, limit):
    cuts = []
    for worker in range(32):
        cuts.append((0, 0))
    index = 0
    count = len(cells)
    for worker in order:
        start = index
        if index < count:
            head = distance(positions[worker], cells[index]) + 1
            budget = limit - head
            if budget >= 0:
                base = prefix[index]
                low = index
                high = count
                while low < high:
                    middle = (low + high) // 2
                    if prefix[middle] - base <= budget:
                        low = middle + 1
                    else:
                        high = middle
                index = low
        cuts[worker] = (start, index)
    return index == count, cuts


